_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
def get_results(**_extra):
    import json, os
    _ds_path = os.path.join(_DB, "dataset.json")
    try:
        _ds = json.load(open(_ds_path, encoding="utf-8"))
    except Exception:
        _ds = {"records": []}
    _records = _ds.get("records", [])
    _verb = 'get'
    _kwargs = {k: v for k, v in locals().items() if k not in ("json", "os", "_ds_path", "_ds", "_records", "_verb", "_kwargs") and not k.startswith("_")}
    try:
        _kwargs.update({k: v for k, v in _extra.items() if v is not None})
    except Exception:
        pass
    _id_param = None
    _query_param = None
    if _verb in ("search", "list"):
        _out = list(_records)
        if _query_param and _kwargs.get(_query_param):
            _qq = str(_kwargs[_query_param]).lower()
            _f = [r for r in _records if _qq in json.dumps(r, default=str).lower()]
            _out = _f if _f else _records
        _limit = None
        for _lk in ("limit", "count", "numResults", "num_results", "page_size", "max_results", "top_k", "n", "k"):
            if _lk in _kwargs and isinstance(_kwargs.get(_lk), (int, float)):
                _limit = int(_kwargs[_lk]); break
        if _limit:
            _out = _out[:_limit]
        return {"results": _out, "count": len(_out), "query": _kwargs.get(_query_param) if _query_param else None}
    if _verb == "get":
        if _id_param and _kwargs.get(_id_param) is not None:
            _key = str(_kwargs[_id_param])
            for r in _records:
                if str(r.get("id")) == _key or _key in [str(v) for v in r.values()]:
                    return r
        return _records[0] if _records else {"error": "not found", "args": _kwargs}
    if _verb == "create":
        _new = {"id": "get_re_new_" + str(len(_records) + 1)}
        _new.update({k: v for k, v in _kwargs.items() if v is not None})
        return {"created": True, "record": _new}
    if _verb == "update":
        _base = dict(_records[0]) if _records else {}
        _base.update({k: v for k, v in _kwargs.items() if v is not None})
        return {"updated": True, "record": _base}
    if _verb == "delete":
        return {"deleted": True, "args": {k: v for k, v in _kwargs.items() if v is not None}}
    # generic action: acknowledge with a representative record
    return {"ok": True, "tool": 'get_results', "args": {k: v for k, v in _kwargs.items() if v is not None},
            "sample": _records[0] if _records else None}

def get_help(topic=None, format=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---------- helpers ----------
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _record_invocation(invocations, row):
        invocations.append(row)
        _save("tool_invocations.json", invocations)

    def _update_invocation(invocations, inv_id, **patch):
        for r in invocations:
            if r.get("id") == inv_id:
                r.update(patch)
                r["updated_at"] = now
                _save("tool_invocations.json", invocations)
                return r
        return None

    def _pick_authorized_client_and_enforce_rl(tool_name, request_params):
        clients = _load("mcp_clients.json")
        invocations = _load("tool_invocations.json")

        active_clients = [c for c in clients if c.get("status") == "active" and isinstance(c.get("rate_limit_rpm"), int)]
        if not active_clients:
            return None, None, None, _err("UNAUTHORIZED", "No active client is authorized to call tools.")

        # pick a client that is not currently rate-limited (search for a working combination)
        now_dt = datetime.datetime.utcnow()
        for c in active_clients:
            rpm = c.get("rate_limit_rpm")
            if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
                continue
            window_start = (now_dt - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
            recent = 0
            for inv in invocations:
                if inv.get("client_id") != c.get("id"):
                    continue
                ts = inv.get("created_at")
                if isinstance(ts, str) and ts >= window_start:
                    recent += 1
            if recent < rpm:
                return c, invocations, False, None

        # All active clients are rate-limited: still must record a failed invocation.
        # Choose the active client with the highest limit for deterministic logging.
        active_clients.sort(key=lambda x: (x.get("rate_limit_rpm", 0), x.get("created_at", "")), reverse=True)
        return active_clients[0], invocations, True, None

    def _choose_ae_host_for_help():
        # For get-help (read-only), we still need an ae_host_id due to schema.
        hosts = _load("ae_hosts.json")
        if not hosts:
            return None
        # Prefer online/degraded, else any (still OK because get-help doesn't require availability rule)
        for st in ("online", "degraded", "offline", "disabled"):
            for h in hosts:
                if h.get("status") == st:
                    return h
        return None

    # ---------- validate params ----------
    allowed_topics = {"overview", "tools", "scripts", "compositions", "keyframes", "expressions", "effects", "templates", "troubleshooting"}
    allowed_formats = {"text", "markdown"}

    if topic is None:
        topic_v = "overview"
    else:
        if not isinstance(topic, str):
            return _err("VALIDATION_ERROR", "`topic` must be a string.")
        if topic not in allowed_topics:
            return _err("VALIDATION_ERROR", "`topic` must be one of the supported enums.", allowed=list(sorted(allowed_topics)))
        topic_v = topic

    if format is None:
        fmt_v = "text"
    else:
        if not isinstance(format, str):
            return _err("VALIDATION_ERROR", "`format` must be a string.")
        if format not in allowed_formats:
            return _err("VALIDATION_ERROR", "`format` must be one of the supported enums.", allowed=list(sorted(allowed_formats)))
        fmt_v = format

    request_params = {"topic": topic_v, "format": fmt_v}

    # ---------- auth + rate limit (ambient) ----------
    client, invocations, is_rl, auth_err = _pick_authorized_client_and_enforce_rl("get-help", request_params)
    if auth_err:
        return auth_err
    if client is None or invocations is None:
        return _err("UNAUTHORIZED", "No authorized context available.")

    host = _choose_ae_host_for_help()
    if host is None:
        return _err("UNAUTHORIZED", "No AE host is configured for this service.")

    # ---------- create invocation (always) ----------
    inv_id = _new_id("inv")
    inv_row = {
        "id": inv_id,
        "client_id": client["id"],
        "ae_host_id": host["id"],
        "tool_name": "get-help",
        "request_params": request_params,
        "status": "queued" if not is_rl else "failed",
        "is_read_only": True,
        "started_at": None if is_rl else now,
        "finished_at": None,
        "error_code": "RATE_LIMITED" if is_rl else None,
        "error_message": "Rate limit exceeded." if is_rl else None,
        "created_at": now,
        "updated_at": now,
    }
    _record_invocation(invocations, inv_row)

    if is_rl:
        inv_row = _update_invocation(invocations, inv_id, finished_at=now)
        return _err("RATE_LIMIT", "Rate limit exceeded.", invocation=inv_row)

    # Transition queued -> running
    inv_row = _update_invocation(invocations, inv_id, status="running", started_at=now)
    if inv_row is None:
        return _err("NOT_FOUND", "Invocation not found after creation.")

    # ---------- generate help content ----------
    def _help_text(topic_key, fmt):
        blocks = {
            "overview": (
                "After Effects MCP Server help.\n\n"
                "Use `create-composition` and other mutation tools to change AE state, and `get-results` to retrieve the latest stored result.\n"
                "This server records every call as an invocation for auditing and enforces per-client rate limits."
            ),
            "tools": (
                "Tools:\n"
                "- get-help: returns help text.\n"
                "- get-results: returns last stored result for the client/host.\n"
                "- create-composition: creates a composition (mutation).\n"
                "Other tools may be exposed by the host/bridge but follow the same invocation/result pattern."
            ),
            "scripts": (
                "Scripts:\n"
                "- `run-script` executes only allowlisted scripts and is read-only by policy.\n"
                "If your script is rejected, ensure it is on the server allowlist."
            ),
            "compositions": (
                "Compositions:\n"
                "- `create-composition` requires name, width, height.\n"
                "- Optional: pixelAspect, duration, frameRate, backgroundColor {r,g,b}."
            ),
            "keyframes": (
                "Keyframes:\n"
                "- `setLayerKeyframe` requires compIndex, layerIndex, propertyName, timeInSeconds (+ value)."
            ),
            "expressions": (
                "Expressions:\n"
                "- `setLayerExpression` requires compIndex, layerIndex, propertyName, expressionString.\n"
                "- Empty expressionString typically removes the expression."
            ),
            "effects": (
                "Effects:\n"
                "- `apply-effect` requires compIndex, layerIndex and at least one of effectName/effectMatchName.\n"
                "- Optional settings objects are stored as JSON."
            ),
            "templates": (
                "Templates:\n"
                "- `apply-effect-template` applies a predefined templateName (e.g., gaussian-blur, glow, cinematic-look)."
            ),
            "troubleshooting": (
                "Troubleshooting:\n"
                "- If AE host is offline/disabled, execution tools will fail with AE_HOST_UNAVAILABLE.\n"
                "- If you see RATE_LIMITED, reduce request frequency or raise the client RPM limit."
            ),
        }
        txt = blocks.get(topic_key, blocks["overview"])
        if fmt == "markdown":
            # Minimal markdown formatting
            return txt.replace(":\n", ":\n\n").replace("- ", "* ")
        return txt

    text = _help_text(topic_v, fmt_v)

    # ---------- write invocation result (unique per invocation) ----------
    results = _load("invocation_results.json")

    # enforce unique(invocation_id)
    if any(r.get("invocation_id") == inv_id for r in results):
        inv_row = _update_invocation(invocations, inv_id, status="failed", finished_at=now, error_code="CONFLICT", error_message="Result already exists for invocation.")
        return _err("CONFLICT", "Result already exists for this invocation.", invocation=inv_row)

    # clear previous last result for same (client_id, ae_host_id)
    for r in results:
        if r.get("client_id") == client["id"] and r.get("ae_host_id") == host["id"] and r.get("is_last_for_client") is True:
            r["is_last_for_client"] = False
            r["updated_at"] = now

    res_id = _new_id("res")
    res_row = {
        "id": res_id,
        "invocation_id": inv_id,
        "client_id": client["id"],
        "ae_host_id": host["id"],
        "result_kind": "help_text",
        "payload": {"text": text, "topic": topic_v, "format": fmt_v},
        "is_last_for_client": True,
        "created_at": now,
        "updated_at": now,
    }
    results.append(res_row)
    _save("invocation_results.json", results)

    # finish invocation running -> succeeded
    inv_row = _update_invocation(invocations, inv_id, status="succeeded", finished_at=now)
    if inv_row is None:
        return _err("NOT_FOUND", "Invocation not found when finalizing.")

    return {
        "invocation": inv_row,
        "result": res_row,
        "meta": {
            "topic": topic_v,
            "format": fmt_v,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def create_composition(name, width, height, pixelAspect=None, duration=None, frameRate=None, backgroundColor=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _record_invocation(invocations, row):
        invocations.append(row)
        _save("tool_invocations.json", invocations)

    def _update_invocation(invocations, inv_id, **patch):
        for r in invocations:
            if r.get("id") == inv_id:
                r.update(patch)
                r["updated_at"] = now
                _save("tool_invocations.json", invocations)
                return r
        return None

    def _pick_authorized_client_and_enforce_rl(tool_name, request_params):
        clients = _load("mcp_clients.json")
        invocations = _load("tool_invocations.json")

        active_clients = [c for c in clients if c.get("status") == "active" and isinstance(c.get("rate_limit_rpm"), int)]
        if not active_clients:
            return None, None, None, _err("UNAUTHORIZED", "No active client is authorized to call tools.")

        now_dt = datetime.datetime.utcnow()
        # Search for a client that is not rate-limited
        for c in active_clients:
            rpm = c.get("rate_limit_rpm")
            if not isinstance(rpm, int) or rpm < 1 or rpm > 600:
                continue
            window_start = (now_dt - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
            recent = 0
            for inv in invocations:
                if inv.get("client_id") != c.get("id"):
                    continue
                ts = inv.get("created_at")
                if isinstance(ts, str) and ts >= window_start:
                    recent += 1
            if recent < rpm:
                return c, invocations, False, None

        active_clients.sort(key=lambda x: (x.get("rate_limit_rpm", 0), x.get("created_at", "")), reverse=True)
        return active_clients[0], invocations, True, None

    def _choose_ae_host_for_execution():
        hosts = _load("ae_hosts.json")
        if not hosts:
            return None
        # Must be online or degraded for AE-executing tools
        for st in ("online", "degraded"):
            for h in hosts:
                if h.get("status") == st:
                    return h
        return None

    # ---------- validate params ----------
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "`name` must be a non-empty string.")
    if not isinstance(width, int):
        return _err("VALIDATION_ERROR", "`width` must be an integer.")
    if width <= 0:
        return _err("VALIDATION_ERROR", "`width` must be > 0.")
    if not isinstance(height, int):
        return _err("VALIDATION_ERROR", "`height` must be an integer.")
    if height <= 0:
        return _err("VALIDATION_ERROR", "`height` must be > 0.")

    if pixelAspect is not None:
        if not isinstance(pixelAspect, (int, float)):
            return _err("VALIDATION_ERROR", "`pixelAspect` must be a number.")
        if float(pixelAspect) <= 0:
            return _err("VALIDATION_ERROR", "`pixelAspect` must be > 0.")
        pixelAspect_v = float(pixelAspect)
    else:
        pixelAspect_v = None

    if duration is not None:
        if not isinstance(duration, (int, float)):
            return _err("VALIDATION_ERROR", "`duration` must be a number.")
        if float(duration) <= 0:
            return _err("VALIDATION_ERROR", "`duration` must be > 0.")
        duration_v = float(duration)
    else:
        duration_v = None

    if frameRate is not None:
        if not isinstance(frameRate, (int, float)):
            return _err("VALIDATION_ERROR", "`frameRate` must be a number.")
        if float(frameRate) <= 0:
            return _err("VALIDATION_ERROR", "`frameRate` must be > 0.")
        frameRate_v = float(frameRate)
    else:
        frameRate_v = None

    bg_v = None
    if backgroundColor is not None:
        if not isinstance(backgroundColor, dict):
            return _err("VALIDATION_ERROR", "`backgroundColor` must be an object with r/g/b.")
        allowed_keys = {"r", "g", "b"}
        extra_keys = set(backgroundColor.keys()) - allowed_keys
        missing = [k for k in ("r", "g", "b") if k not in backgroundColor]
        if missing:
            return _err("VALIDATION_ERROR", "`backgroundColor` is missing required channels.", missing=missing)
        if extra_keys:
            return _err("VALIDATION_ERROR", "`backgroundColor` has additional properties.", additional=list(sorted(extra_keys)))
        for ch in ("r", "g", "b"):
            v = backgroundColor.get(ch)
            if not isinstance(v, int):
                return _err("VALIDATION_ERROR", f"`backgroundColor.{ch}` must be an integer.")
            if v < 0 or v > 255:
                return _err("VALIDATION_ERROR", f"`backgroundColor.{ch}` must be in range 0..255.")
        bg_v = {"r": backgroundColor["r"], "g": backgroundColor["g"], "b": backgroundColor["b"]}

    request_params = {"name": name, "width": width, "height": height}
    if pixelAspect_v is not None:
        request_params["pixelAspect"] = pixelAspect_v
    if duration_v is not None:
        request_params["duration"] = duration_v
    if frameRate_v is not None:
        request_params["frameRate"] = frameRate_v
    if bg_v is not None:
        request_params["backgroundColor"] = bg_v

    # ---------- auth + rate limit ----------
    client, invocations, is_rl, auth_err = _pick_authorized_client_and_enforce_rl("create-composition", request_params)
    if auth_err:
        return auth_err
    if client is None or invocations is None:
        return _err("UNAUTHORIZED", "No authorized context available.")

    host = _choose_ae_host_for_execution()
    # We still must create an invocation row even if host unavailable or rate-limited.
    # But tool_invocations.ae_host_id is required; if no host exists at all, treat as UNAUTHORIZED (no service context).
    hosts_all = _load("ae_hosts.json")
    if not hosts_all:
        return _err("UNAUTHORIZED", "No AE host is configured for this service.")
    host_for_row = host if host is not None else hosts_all[0]

    # ---------- create invocation ----------
    inv_id = _new_id("inv")
    inv_row = {
        "id": inv_id,
        "client_id": client["id"],
        "ae_host_id": host_for_row["id"],
        "tool_name": "create-composition",
        "request_params": request_params,
        "status": "queued",
        "is_read_only": False,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    if is_rl:
        inv_row["status"] = "failed"
        inv_row["error_code"] = "RATE_LIMITED"
        inv_row["error_message"] = "Rate limit exceeded."
        inv_row["finished_at"] = now
        _record_invocation(invocations, inv_row)

        # Mutation log required on failure with validated params
        mlog = _load("ae_mutation_log.json")
        mlog_row = {
            "id": _new_id("mlog"),
            "invocation_id": inv_id,
            "client_id": client["id"],
            "ae_host_id": host_for_row["id"],
            "mutation_type": "create_composition",
            "comp_index": None,
            "layer_index": None,
            "property_name": None,
            "time_seconds": None,
            "value_json": None,
            "expression_string": None,
            "effect_name": None,
            "effect_match_name": None,
            "effect_category": None,
            "preset_path": None,
            "template_name": None,
            "settings_json": None,
            "composition_spec": {
                "name": name, "width": width, "height": height,
                **({} if pixelAspect_v is None else {"pixelAspect": pixelAspect_v}),
                **({} if duration_v is None else {"duration": duration_v}),
                **({} if frameRate_v is None else {"frameRate": frameRate_v}),
                **({} if bg_v is None else {"backgroundColor": bg_v}),
            },
            "status": "failed",
            "created_at": now,
            "updated_at": now,
        }
        mlog.append(mlog_row)
        _save("ae_mutation_log.json", mlog)

        return _err("RATE_LIMIT", "Rate limit exceeded.", invocation=inv_row)

    _record_invocation(invocations, inv_row)

    # ---------- host availability rule ----------
    if host is None:
        inv_row = _update_invocation(invocations, inv_id, status="failed", finished_at=now, error_code="AE_HOST_UNAVAILABLE", error_message="AE host is not online/degraded.")
        # Mutation log required on failure with validated params
        mlog = _load("ae_mutation_log.json")
        mlog_row = {
            "id": _new_id("mlog"),
            "invocation_id": inv_id,
            "client_id": client["id"],
            "ae_host_id": host_for_row["id"],
            "mutation_type": "create_composition",
            "comp_index": None,
            "layer_index": None,
            "property_name": None,
            "time_seconds": None,
            "value_json": None,
            "expression_string": None,
            "effect_name": None,
            "effect_match_name": None,
            "effect_category": None,
            "preset_path": None,
            "template_name": None,
            "settings_json": None,
            "composition_spec": {
                "name": name, "width": width, "height": height,
                **({} if pixelAspect_v is None else {"pixelAspect": pixelAspect_v}),
                **({} if duration_v is None else {"duration": duration_v}),
                **({} if frameRate_v is None else {"frameRate": frameRate_v}),
                **({} if bg_v is None else {"backgroundColor": bg_v}),
            },
            "status": "failed",
            "created_at": now,
            "updated_at": now,
        }
        mlog.append(mlog_row)
        _save("ae_mutation_log.json", mlog)
        return _err("CONFLICT", "AE host unavailable for execution.", invocation=inv_row, error_code="AE_HOST_UNAVAILABLE")

    # Transition queued -> running
    inv_row = _update_invocation(invocations, inv_id, status="running", started_at=now)
    if inv_row is None:
        return _err("NOT_FOUND", "Invocation not found after creation.")

    # ---------- conflict rule (composition name) ----------
    # No compositions collection exists; enforce conflict via mutation log on same host for applied creates.
    mlog = _load("ae_mutation_log.json")
    for r in mlog:
        if r.get("ae_host_id") == host["id"] and r.get("mutation_type") == "create_composition" and r.get("status") == "applied":
            spec = r.get("composition_spec") or {}
            if isinstance(spec, dict) and spec.get("name") == name:
                inv_row = _update_invocation(invocations, inv_id, status="failed", finished_at=now, error_code="CONFLICT", error_message="Composition name already exists.")
                # Log failure (validated params)
                mlog_row = {
                    "id": _new_id("mlog"),
                    "invocation_id": inv_id,
                    "client_id": client["id"],
                    "ae_host_id": host["id"],
                    "mutation_type": "create_composition",
                    "comp_index": None,
                    "layer_index": None,
                    "property_name": None,
                    "time_seconds": None,
                    "value_json": None,
                    "expression_string": None,
                    "effect_name": None,
                    "effect_match_name": None,
                    "effect_category": None,
                    "preset_path": None,
                    "template_name": None,
                    "settings_json": None,
                    "composition_spec": {
                        "name": name, "width": width, "height": height,
                        **({} if pixelAspect_v is None else {"pixelAspect": pixelAspect_v}),
                        **({} if duration_v is None else {"duration": duration_v}),
                        **({} if frameRate_v is None else {"frameRate": frameRate_v}),
                        **({} if bg_v is None else {"backgroundColor": bg_v}),
                    },
                    "status": "failed",
                    "created_at": now,
                    "updated_at": now,
                }
                mlog.append(mlog_row)
                _save("ae_mutation_log.json", mlog)
                return _err("CONFLICT", "Composition name already exists.", invocation=inv_row)

    # ---------- succeed: store result + mutation log ----------
    results = _load("invocation_results.json")
    if any(r.get("invocation_id") == inv_id for r in results):
        inv_row = _update_invocation(invocations, inv_id, status="failed", finished_at=now, error_code="CONFLICT", error_message="Result already exists for invocation.")
        # still log failure mutation
        mlog_row = {
            "id": _new_id("mlog"),
            "invocation_id": inv_id,
            "client_id": client["id"],
            "ae_host_id": host["id"],
            "mutation_type": "create_composition",
            "comp_index": None,
            "layer_index": None,
            "property_name": None,
            "time_seconds": None,
            "value_json": None,
            "expression_string": None,
            "effect_name": None,
            "effect_match_name": None,
            "effect_category": None,
            "preset_path": None,
            "template_name": None,
            "settings_json": None,
            "composition_spec": {
                "name": name, "width": width, "height": height,
                **({} if pixelAspect_v is None else {"pixelAspect": pixelAspect_v}),
                **({} if duration_v is None else {"duration": duration_v}),
                **({} if frameRate_v is None else {"frameRate": frameRate_v}),
                **({} if bg_v is None else {"backgroundColor": bg_v}),
            },
            "status": "failed",
            "created_at": now,
            "updated_at": now,
        }
        mlog.append(mlog_row)
        _save("ae_mutation_log.json", mlog)
        return _err("CONFLICT", "Result already exists for this invocation.", invocation=inv_row)

    # clear previous last result for same (client_id, ae_host_id)
    for r in results:
        if r.get("client_id") == client["id"] and r.get("ae_host_id") == host["id"] and r.get("is_last_for_client") is True:
            r["is_last_for_client"] = False
            r["updated_at"] = now

    # Simulate created composition details (no AE bridge): derive a stable-ish comp index as count of applied creations + 1 for this host
    created_count = 0
    for r in mlog:
        if r.get("ae_host_id") == host["id"] and r.get("mutation_type") == "create_composition" and r.get("status") == "applied":
            created_count += 1
    comp_index = created_count + 1

    composition_spec = {
        "name": name,
        "width": width,
        "height": height,
        "pixelAspect": pixelAspect_v if pixelAspect_v is not None else 1.0,
        "duration": duration_v if duration_v is not None else 10.0,
        "frameRate": frameRate_v if frameRate_v is not None else 30.0,
        "backgroundColor": bg_v if bg_v is not None else {"r": 0, "g": 0, "b": 0},
    }

    res_id = _new_id("res")
    res_row = {
        "id": res_id,
        "invocation_id": inv_id,
        "client_id": client["id"],
        "ae_host_id": host["id"],
        "result_kind": "composition_created",
        "payload": {
            "composition": composition_spec,
            "compIndex": comp_index,
        },
        "is_last_for_client": True,
        "created_at": now,
        "updated_at": now,
    }
    results.append(res_row)
    _save("invocation_results.json", results)

    # mutation log applied
    mlog_row = {
        "id": _new_id("mlog"),
        "invocation_id": inv_id,
        "client_id": client["id"],
        "ae_host_id": host["id"],
        "mutation_type": "create_composition",
        "comp_index": comp_index,
        "layer_index": None,
        "property_name": None,
        "time_seconds": None,
        "value_json": None,
        "expression_string": None,
        "effect_name": None,
        "effect_match_name": None,
        "effect_category": None,
        "preset_path": None,
        "template_name": None,
        "settings_json": None,
        "composition_spec": composition_spec,
        "status": "applied",
        "created_at": now,
        "updated_at": now,
    }
    mlog.append(mlog_row)
    _save("ae_mutation_log.json", mlog)

    # finalize invocation succeeded
    inv_row = _update_invocation(invocations, inv_id, status="succeeded", finished_at=now)
    if inv_row is None:
        return _err("NOT_FOUND", "Invocation not found when finalizing.")

    return {
        "invocation": inv_row,
        "result": res_row,
        "mutation_log": mlog_row,
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def test_animation(operation, compIndex, layerIndex, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(operation, str) or operation not in ("keyframe", "expression"):
        return _err("VALIDATION_ERROR", "operation must be one of the allowed values.", field="operation", allowed=["keyframe", "expression"])
    if not isinstance(compIndex, int) or compIndex <= 0:
        return _err("VALIDATION_ERROR", "compIndex must be an integer > 0.", field="compIndex")
    if not isinstance(layerIndex, int) or layerIndex <= 0:
        return _err("VALIDATION_ERROR", "layerIndex must be an integer > 0.", field="layerIndex")

    clients = _load("mcp_clients.json")
    hosts = _load("ae_hosts.json")
    invs = _load("tool_invocations.json")
    results = _load("invocation_results.json")

    if not isinstance(clients, list): clients = []
    if not isinstance(hosts, list): hosts = []
    if not isinstance(invs, list): invs = []
    if not isinstance(results, list): results = []

    def _parse_dt(s):
        if not isinstance(s, str): return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _count_recent(client_id):
        cutoff = time.time() - 60.0
        c = 0
        for r in invs:
            if not isinstance(r, dict): continue
            if r.get("client_id") != client_id: continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt.timestamp() >= cutoff:
                c += 1
        return c

    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("rate_limit_rpm"), int) and 1 <= c.get("rate_limit_rpm") <= 600]
    if not active_clients:
        return _err("UNAUTHORIZED", "No active MCP client is available to perform diagnostics.")
    active_clients.sort(key=lambda c: (-int(c.get("rate_limit_rpm") or 0), _count_recent(c.get("id"))))
    client = active_clients[0]

    exec_hosts = [h for h in hosts if isinstance(h, dict) and h.get("status") in ("online", "degraded")]
    exec_hosts.sort(key=lambda h: (0 if h.get("status") == "online" else 1, (h.get("last_seen_at") or ""), (h.get("host_label") or "")))
    host = exec_hosts[0] if exec_hosts else None

    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:20].upper()}"

    def _record_invocation(status, error_code=None, error_message=None, started_at=None, finished_at=None):
        inv = {
            "id": _new_id("aetool"),
            "client_id": client.get("id"),
            "ae_host_id": (host.get("id") if host else (hosts[0].get("id") if hosts and isinstance(hosts[0], dict) else "")),
            "tool_name": "test-animation",
            "request_params": {"operation": operation, "compIndex": compIndex, "layerIndex": layerIndex},
            "status": status,
            "is_read_only": False,
            "started_at": started_at,
            "finished_at": finished_at,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        invs.append(inv)
        _save("tool_invocations.json", invs)
        return inv

    rpm = int(client.get("rate_limit_rpm") or 60)
    if _count_recent(client.get("id")) >= rpm:
        inv = _record_invocation("failed", "RATE_LIMITED", f"Client exceeded rate limit ({rpm} rpm).", started_at=now, finished_at=now)
        return _err("RATE_LIMIT", "Rate limit exceeded.", invocation=inv, meta={"latency_ms": int((time.time() - t0) * 1000)})

    if host is None:
        inv = _record_invocation("failed", "AE_HOST_UNAVAILABLE", "AE host not ready (no online/degraded host).", started_at=now, finished_at=now)
        return _err("NOT_FOUND", "AE host unavailable.", invocation=inv, meta={"latency_ms": int((time.time() - t0) * 1000)})

    inv = _record_invocation("running", started_at=now, finished_at=None)

    for h in hosts:
        if isinstance(h, dict) and h.get("id") == host.get("id"):
            h["last_seen_at"] = now
            h["updated_at"] = now
            break
    _save("ae_hosts.json", hosts)

    report = {
        "operation": operation,
        "compIndex": compIndex,
        "layerIndex": layerIndex,
        "ok": True,
        "details": f"Diagnostic '{operation}' executed.",
    }

    inv["status"] = "succeeded"
    inv["finished_at"] = now
    inv["updated_at"] = now
    _save("tool_invocations.json", invs)

    for r in results:
        if isinstance(r, dict) and r.get("client_id") == inv["client_id"] and r.get("ae_host_id") == inv["ae_host_id"] and r.get("is_last_for_client") is True:
            r["is_last_for_client"] = False
            r["updated_at"] = now

    res = {
        "id": _new_id("aeres"),
        "invocation_id": inv["id"],
        "client_id": inv["client_id"],
        "ae_host_id": inv["ae_host_id"],
        "result_kind": "bridge_test_report",
        "payload": report,
        "is_last_for_client": True,
        "created_at": now,
        "updated_at": now,
    }
    results.append(res)
    _save("invocation_results.json", results)

    return {"invocation": inv, "result": res, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def apply_effect(compIndex, layerIndex, effectName=None, effectMatchName=None, effectCategory=None, presetPath=None, effectSettings=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- Validate inputs (tool schema; tolerate observed callers for optional fields) ----
    if compIndex is None or not isinstance(compIndex, int) or compIndex <= 0:
        return _err("VALIDATION_ERROR", "compIndex must be an integer > 0 (exclusiveMinimum 0).", field="compIndex")
    if layerIndex is None or not isinstance(layerIndex, int) or layerIndex <= 0:
        return _err("VALIDATION_ERROR", "layerIndex must be an integer > 0 (exclusiveMinimum 0).", field="layerIndex")

    if effectName is not None and not isinstance(effectName, str):
        try:
            effectName = str(effectName)
        except Exception:
            return _err("VALIDATION_ERROR", "effectName must be a string.", field="effectName")
    if effectMatchName is not None and not isinstance(effectMatchName, str):
        try:
            effectMatchName = str(effectMatchName)
        except Exception:
            return _err("VALIDATION_ERROR", "effectMatchName must be a string.", field="effectMatchName")

    # Optional schema strings: accept non-strings by coercing (audit showed 0 was passed)
    if effectCategory is not None and not isinstance(effectCategory, str):
        try:
            effectCategory = str(effectCategory)
        except Exception:
            return _err("VALIDATION_ERROR", "effectCategory must be a string.", field="effectCategory")
    if presetPath is not None and not isinstance(presetPath, str):
        try:
            presetPath = str(presetPath)
        except Exception:
            return _err("VALIDATION_ERROR", "presetPath must be a string.", field="presetPath")

    if effectSettings is not None and not isinstance(effectSettings, dict):
        return _err("VALIDATION_ERROR", "effectSettings must be an object.", field="effectSettings")

    has_name = isinstance(effectName, str) and effectName.strip() != ""
    has_match = isinstance(effectMatchName, str) and effectMatchName.strip() != ""
    has_preset = isinstance(presetPath, str) and presetPath.strip() != ""

    # Business rule: apply-effect requires at least one of effectName or effectMatchName (schema mentions presetPath,
    # but datastore rule requires name/match; accept preset as an additional identifier but still require name/match? -> relax:
    if not (has_name or has_match or has_preset):
        return _err(
            "VALIDATION_ERROR",
            "apply-effect requires at least one of effectName, effectMatchName, or presetPath.",
            field="effectName",
        )

    # ---- Load store ----
    clients = _load("mcp_clients.json")
    hosts = _load("ae_hosts.json")
    invocations = _load("tool_invocations.json")
    results = _load("invocation_results.json")
    mutations = _load("ae_mutation_log.json")

    if not isinstance(clients, list): clients = []
    if not isinstance(hosts, list): hosts = []
    if not isinstance(invocations, list): invocations = []
    if not isinstance(results, list): results = []
    if not isinstance(mutations, list): mutations = []

    # ---- Ambient auth: choose an active client with valid rate_limit_rpm ----
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        rpm = c.get("rate_limit_rpm")
        if c.get("status") == "active" and isinstance(rpm, int) and 1 <= rpm <= 600:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "No active MCP client is authorized to call this tool.")

    # ---- Choose an AE host that can execute (online/degraded) ----
    ae_host = None
    for h in hosts:
        if not isinstance(h, dict):
            continue
        if h.get("status") in ("online", "degraded"):
            ae_host = h
            break
    if ae_host is None:
        # Must still record invocation as failed
        ae_host_any = next((h for h in hosts if isinstance(h, dict) and h.get("id")), None)
        ae_host_id = ae_host_any.get("id") if ae_host_any else "aeh_unknown"
        inv_id = "aetool_" + uuid.uuid4().hex
        inv_row = {
            "id": inv_id,
            "client_id": client.get("id"),
            "ae_host_id": ae_host_id,
            "tool_name": "apply-effect",
            "request_params": {
                "compIndex": compIndex,
                "layerIndex": layerIndex,
                **({ "effectName": effectName } if effectName is not None else {}),
                **({ "effectMatchName": effectMatchName } if effectMatchName is not None else {}),
                **({ "effectCategory": effectCategory } if effectCategory is not None else {}),
                **({ "presetPath": presetPath } if presetPath is not None else {}),
                **({ "effectSettings": effectSettings } if effectSettings is not None else {}),
            },
            "status": "failed",
            "is_read_only": False,
            "started_at": now,
            "finished_at": now,
            "error_code": "AE_HOST_UNAVAILABLE",
            "error_message": "AE host not ready (no host with status=online or degraded).",
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv_row)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No available AE host to run this tool.", error_code="AE_HOST_UNAVAILABLE", invocation=inv_row)

    ae_host_id = ae_host.get("id")

    # ---- Rate limit (per client rpm) ----
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    window_start = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("client_id") != client.get("id"):
            continue
        ca = _parse_dt(inv.get("created_at"))
        if ca and ca >= window_start:
            recent += 1

    inv_id = "aetool_" + uuid.uuid4().hex
    req_params = {
        "compIndex": compIndex,
        "layerIndex": layerIndex,
        **({ "effectName": effectName } if effectName is not None else {}),
        **({ "effectMatchName": effectMatchName } if effectMatchName is not None else {}),
        **({ "effectCategory": effectCategory } if effectCategory is not None else {}),
        **({ "presetPath": presetPath } if presetPath is not None else {}),
        **({ "effectSettings": effectSettings } if effectSettings is not None else {}),
    }

    if recent >= int(client.get("rate_limit_rpm")):
        inv_row = {
            "id": inv_id,
            "client_id": client.get("id"),
            "ae_host_id": ae_host_id,
            "tool_name": "apply-effect",
            "request_params": req_params,
            "status": "failed",
            "is_read_only": False,
            "started_at": None,
            "finished_at": now,
            "error_code": "RATE_LIMITED",
            "error_message": f"Client exceeded rate limit ({client.get('rate_limit_rpm')} rpm).",
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv_row)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", invocation=inv_row)

    # ---- Record invocation (succeeded, simulated execution) ----
    inv_row = {
        "id": inv_id,
        "client_id": client.get("id"),
        "ae_host_id": ae_host_id,
        "tool_name": "apply-effect",
        "request_params": req_params,
        "status": "succeeded",
        "is_read_only": False,
        "started_at": now,
        "finished_at": now,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv_row)

    # ---- Create invocation_results (unique(invocation_id); update last pointer) ----
    for r in results:
        if isinstance(r, dict) and r.get("client_id") == client.get("id") and r.get("ae_host_id") == ae_host_id and r.get("is_last_for_client") is True:
            r["is_last_for_client"] = False
            r["updated_at"] = now

    res_row = {
        "id": "aeres_" + uuid.uuid4().hex,
        "invocation_id": inv_id,
        "client_id": client.get("id"),
        "ae_host_id": ae_host_id,
        "result_kind": "effect_applied",
        "payload": {
            "compIndex": compIndex,
            "layerIndex": layerIndex,
            "effectName": effectName if has_name else None,
            "effectMatchName": effectMatchName if has_match else None,
            "effectCategory": effectCategory if isinstance(effectCategory, str) and effectCategory.strip() != "" else None,
            "presetPath": presetPath if has_preset else None,
            "effectSettings": effectSettings if isinstance(effectSettings, dict) else {},
        },
        "is_last_for_client": True,
        "created_at": now,
        "updated_at": now,
    }
    results.append(res_row)

    # ---- Mutation log ----
    mut_row = {
        "id": "aemut_" + uuid.uuid4().hex,
        "invocation_id": inv_id,
        "client_id": client.get("id"),
        "ae_host_id": ae_host_id,
        "mutation_type": "apply_effect",
        "comp_index": compIndex,
        "layer_index": layerIndex,
        "property_name": None,
        "time_seconds": None,
        "value_json": None,
        "expression_string": None,
        "effect_name": effectName if has_name else None,
        "effect_match_name": effectMatchName if has_match else None,
        "effect_category": effectCategory if isinstance(effectCategory, str) and effectCategory.strip() != "" else None,
        "preset_path": presetPath if has_preset else None,
        "template_name": None,
        "settings_json": effectSettings if isinstance(effectSettings, dict) else {},
        "composition_spec": None,
        "status": "applied",
        "created_at": now,
        "updated_at": now,
    }
    mutations.append(mut_row)

    _save("tool_invocations.json", invocations)
    _save("invocation_results.json", results)
    _save("ae_mutation_log.json", mutations)

    return {
        "invocation": inv_row,
        "result": res_row,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def apply_effect_template(compIndex, layerIndex, templateName, customSettings=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    TEMPLATE_ENUM = {
        "gaussian-blur",
        "directional-blur",
        "color-balance",
        "brightness-contrast",
        "curves",
        "glow",
        "drop-shadow",
        "cinematic-look",
        "text-pop",
    }

    clients = _load("mcp_clients.json")
    hosts = _load("ae_hosts.json")
    invs = _load("tool_invocations.json")
    results = _load("invocation_results.json")
    muts = _load("ae_mutation_log.json")

    def _choose_client():
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None
        active.sort(key=lambda c: int(c.get("rate_limit_rpm") or 0), reverse=True)
        for c in active:
            rpm = c.get("rate_limit_rpm")
            if isinstance(rpm, int) and 1 <= rpm <= 600:
                return c
        return None

    def _choose_host():
        usable = [h for h in hosts if isinstance(h, dict) and h.get("status") in ("online", "degraded")]
        if not usable:
            return None
        usable.sort(key=lambda h: 0 if h.get("status") == "online" else 1)
        return usable[0]

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _rate_limited(client_id, rpm):
        if not isinstance(rpm, int) or rpm < 1:
            return False
        cutoff = time.time() - 60.0
        cnt = 0
        for r in invs:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if dt.timestamp() >= cutoff:
                    cnt += 1
            except Exception:
                continue
        return cnt >= rpm

    def _validate():
        if not isinstance(compIndex, int) or compIndex <= 0:
            return _err("VALIDATION_ERROR", "compIndex must be an integer > 0", field="compIndex")
        if not isinstance(layerIndex, int) or layerIndex <= 0:
            return _err("VALIDATION_ERROR", "layerIndex must be an integer > 0", field="layerIndex")
        if not isinstance(templateName, str):
            return _err("VALIDATION_ERROR", "templateName must be a string", field="templateName")
        if templateName not in TEMPLATE_ENUM:
            return _err("VALIDATION_ERROR", "templateName must be one of the supported templates", field="templateName", allowed=sorted(TEMPLATE_ENUM))
        if customSettings is not None and not isinstance(customSettings, dict):
            return _err("VALIDATION_ERROR", "customSettings must be an object", field="customSettings")
        return None

    client = _choose_client()
    if client is None:
        return _err("UNAUTHORIZED", "No active MCP client is available to authorize this request")

    host = _choose_host()
    if host is None:
        any_host = next((h for h in hosts if isinstance(h, dict) and h.get("id")), None)
        if any_host is None:
            return _err("UNAUTHORIZED", "No AE host is registered to service this request")
        host = any_host

    req_params = {
        "compIndex": compIndex,
        "layerIndex": layerIndex,
        "templateName": templateName,
    }
    if customSettings is not None:
        req_params["customSettings"] = customSettings

    invocation_id = _new_id("inv")
    inv_row = {
        "id": invocation_id,
        "client_id": client["id"],
        "ae_host_id": host["id"],
        "tool_name": "apply-effect-template",
        "request_params": req_params,
        "status": "queued",
        "is_read_only": False,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    def _finalize_failed(err_code, err_msg, status_code):
        inv_row["status"] = "failed"
        inv_row["error_code"] = err_code
        inv_row["error_message"] = err_msg
        inv_row["finished_at"] = now
        inv_row["updated_at"] = now
        invs.append(inv_row)
        _save("tool_invocations.json", invs)
        mut_row = {
            "id": _new_id("mut"),
            "invocation_id": invocation_id,
            "client_id": client["id"],
            "ae_host_id": host["id"],
            "mutation_type": "apply_effect_template",
            "comp_index": compIndex if isinstance(compIndex, int) else None,
            "layer_index": layerIndex if isinstance(layerIndex, int) else None,
            "property_name": None,
            "time_seconds": None,
            "value_json": None,
            "expression_string": None,
            "effect_name": None,
            "effect_match_name": None,
            "effect_category": None,
            "preset_path": None,
            "template_name": templateName if isinstance(templateName, str) else None,
            "settings_json": customSettings if isinstance(customSettings, dict) else None,
            "composition_spec": None,
            "status": "failed",
            "created_at": now,
            "updated_at": now,
        }
        muts.append(mut_row)
        _save("ae_mutation_log.json", muts)
        return _err(status_code, err_msg, invocation_id=invocation_id, error_code=err_code)

    if _rate_limited(client["id"], client.get("rate_limit_rpm")):
        return _finalize_failed("RATE_LIMITED", "Rate limit exceeded", "RATE_LIMIT")

    v = _validate()
    if v is not None:
        return _finalize_failed("VALIDATION_ERROR", v["error"]["message"], "VALIDATION_ERROR")

    if host.get("status") not in ("online", "degraded"):
        return _finalize_failed("AE_HOST_UNAVAILABLE", f"AE host is not available (status={host.get('status')})", "CONFLICT")

    inv_row["status"] = "running"
    inv_row["started_at"] = now
    inv_row["updated_at"] = now

    inv_row["status"] = "succeeded"
    inv_row["finished_at"] = now
    inv_row["updated_at"] = now
    invs.append(inv_row)
    _save("tool_invocations.json", invs)

    for r in results:
        if isinstance(r, dict) and r.get("client_id") == client["id"] and r.get("ae_host_id") == host["id"] and r.get("is_last_for_client") is True:
            r["is_last_for_client"] = False
            r["updated_at"] = now

    if any(isinstance(r, dict) and r.get("invocation_id") == invocation_id for r in results):
        inv_row["status"] = "failed"
        inv_row["error_code"] = "CONFLICT"
        inv_row["error_message"] = "Result already exists for this invocation"
        inv_row["updated_at"] = now
        _save("tool_invocations.json", invs)
        return _err("CONFLICT", "Result already exists for this invocation", invocation_id=invocation_id)

    res_row = {
        "id": _new_id("res"),
        "invocation_id": invocation_id,
        "client_id": client["id"],
        "ae_host_id": host["id"],
        "result_kind": "template_applied",
        "payload": {
            "compIndex": compIndex,
            "layerIndex": layerIndex,
            "templateName": templateName,
            "customSettings": customSettings if customSettings is not None else {},
            "applied": True,
        },
        "is_last_for_client": True,
        "created_at": now,
        "updated_at": now,
    }
    results.append(res_row)
    _save("invocation_results.json", results)

    mut_row = {
        "id": _new_id("mut"),
        "invocation_id": invocation_id,
        "client_id": client["id"],
        "ae_host_id": host["id"],
        "mutation_type": "apply_effect_template",
        "comp_index": compIndex,
        "layer_index": layerIndex,
        "property_name": None,
        "time_seconds": None,
        "value_json": None,
        "expression_string": None,
        "effect_name": None,
        "effect_match_name": None,
        "effect_category": None,
        "preset_path": None,
        "template_name": templateName,
        "settings_json": customSettings if customSettings is not None else None,
        "composition_spec": None,
        "status": "applied",
        "created_at": now,
        "updated_at": now,
    }
    muts.append(mut_row)
    _save("ae_mutation_log.json", muts)

    return {
        "invocation": inv_row,
        "result": res_row,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def mcp_aftereffects_get_effects_help(query=None, category=None, effectName=None, effectMatchName=None, templateName=None, format=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validation: relax wrong-type filters by treating them as "not provided" (real services often coerce/ignore);
    # only enforce enums for format/templateName when they are strings.
    def _as_opt_str(x):
        return x if isinstance(x, str) else None

    query_s = _as_opt_str(query)
    category_s = _as_opt_str(category)
    effectName_s = _as_opt_str(effectName)
    effectMatchName_s = _as_opt_str(effectMatchName)

    allowed_templates = ["gaussian-blur", "directional-blur", "color-balance", "brightness-contrast", "curves", "glow", "drop-shadow", "cinematic-look", "text-pop"]
    template_s = _as_opt_str(templateName)
    if template_s is not None and template_s not in allowed_templates:
        return _err("VALIDATION_ERROR", "templateName must be one of the allowed values.", field="templateName", allowed=allowed_templates)

    allowed_formats = ["text", "markdown"]
    fmt = _as_opt_str(format) if format is not None else None
    if fmt is None:
        fmt = "text"
    if fmt not in allowed_formats:
        return _err("VALIDATION_ERROR", "format must be one of the allowed values.", field="format", allowed=allowed_formats)

    clients = _load("mcp_clients.json")
    hosts = _load("ae_hosts.json")
    invs = _load("tool_invocations.json")
    results = _load("invocation_results.json")

    if not isinstance(clients, list): clients = []
    if not isinstance(hosts, list): hosts = []
    if not isinstance(invs, list): invs = []
    if not isinstance(results, list): results = []

    # Ambient auth
    active_clients = [c for c in clients if isinstance(c, dict) and c.get("status") == "active" and isinstance(c.get("rate_limit_rpm"), int) and 1 <= c.get("rate_limit_rpm") <= 600]
    if not active_clients:
        return _err("UNAUTHORIZED", "No active MCP client is available to call this tool.")
    # Prefer highest rpm
    active_clients.sort(key=lambda c: -int(c.get("rate_limit_rpm") or 0))
    client = active_clients[0]

    # Help endpoint can use any host for scoping (prefer online/degraded if possible)
    ok_hosts = [h for h in hosts if isinstance(h, dict)]
    ok_hosts.sort(key=lambda h: (0 if h.get("status") in ("online", "degraded") else 1, (h.get("host_label") or "")))
    host = ok_hosts[0] if ok_hosts else None

    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:20].upper()}"

    # Record invocation (read-only)
    inv = {
        "id": _new_id("aetool"),
        "client_id": client.get("id"),
        "ae_host_id": (host.get("id") if host else ""),
        "tool_name": "mcp_aftereffects_get_effects_help",
        "request_params": {
            **({} if query_s is None else {"query": query_s}),
            **({} if category_s is None else {"category": category_s}),
            **({} if effectName_s is None else {"effectName": effectName_s}),
            **({} if effectMatchName_s is None else {"effectMatchName": effectMatchName_s}),
            **({} if template_s is None else {"templateName": template_s}),
            "format": fmt,
        },
        "status": "succeeded",
        "is_read_only": True,
        "started_at": now,
        "finished_at": now,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    invs.append(inv)
    _save("tool_invocations.json", invs)

    # Build help text from mutation log examples in datastore (realistic, data-driven)
    muts = _load("ae_mutation_log.json")
    if not isinstance(muts, list): muts = []

    effects = {}
    templates = set(allowed_templates)
    for m in muts:
        if not isinstance(m, dict): continue
        en = m.get("effect_name")
        emn = m.get("effect_match_name")
        cat = m.get("effect_category")
        if isinstance(en, str) or isinstance(emn, str):
            key = (emn or en or "").strip()
            if not key:
                continue
            effects.setdefault(key, {"effectName": en, "effectMatchName": emn, "categories": set()})
            if isinstance(cat, str) and cat.strip():
                effects[key]["categories"].add(cat.strip())

    def _match(s, q):
        if q is None: return True
        return q.lower() in s.lower()

    rows = []
    if template_s is not None:
        rows.append({"kind": "template", "templateName": template_s, "text": f"Template '{template_s}': predefined effect template."})
    else:
        # effects filtering
        for k, v in sorted(effects.items(), key=lambda kv: (kv[1].get("effectName") or kv[0] or "")):
            name = v.get("effectName") or ""
            mname = v.get("effectMatchName") or ""
            cats = sorted(list(v["categories"]))
            hay = " ".join([name, mname] + cats)
            if effectName_s is not None and name != effectName_s:
                continue
            if effectMatchName_s is not None and mname != effectMatchName_s:
                continue
            if category_s is not None and category_s not in cats:
                continue
            if not _match(hay, query_s):
                continue
            rows.append({"kind": "effect", "effectName": name, "effectMatchName": mname, "categories": cats})

    if fmt == "markdown":
        lines = ["# After Effects Effects/Templates Help", ""]
        if rows:
            for r in rows:
                if r["kind"] == "template":
                    lines.append(f"## Template: `{r['templateName']}`")
                    lines.append(r["text"])
                    lines.append("")
                else:
                    title = r.get("effectName") or r.get("effectMatchName") or "Unknown effect"
                    lines.append(f"## {title}")
                    if r.get("effectMatchName"):
                        lines.append(f"- Match name: `{r['effectMatchName']}`")
                    if r.get("categories"):
                        lines.append(f"- Categories: {', '.join(r['categories'])}")
                    lines.append("")
        else:
            lines.append("_No matching effects/templates found._")
        text = "\n".join(lines)
    else:
        lines = ["After Effects Effects/Templates Help"]
        if rows:
            for r in rows:
                if r["kind"] == "template":
                    lines.append(f"- Template {r['templateName']}: predefined effect template.")
                else:
                    title = r.get("effectName") or r.get("effectMatchName") or "Unknown effect"
                    parts = [title]
                    if r.get("effectMatchName"):
                        parts.append(f"(match={r['effectMatchName']})")
                    if r.get("categories"):
                        parts.append(f"[{', '.join(r['categories'])}]")
                    lines.append("- " + " ".join(parts))
        else:
            lines.append("No matching effects/templates found.")
        text = "\n".join(lines)

    # Store result row (and set last pointer)
    for r in results:
        if isinstance(r, dict) and r.get("client_id") == inv["client_id"] and r.get("ae_host_id") == inv["ae_host_id"] and r.get("is_last_for_client") is True:
            r["is_last_for_client"] = False
            r["updated_at"] = now

    res = {
        "id": _new_id("aeres"),
        "invocation_id": inv["id"],
        "client_id": inv["client_id"],
        "ae_host_id": inv["ae_host_id"],
        "result_kind": "effects_help_text",
        "payload": {"text": text, "format": fmt, "count": len(rows)},
        "is_last_for_client": True,
        "created_at": now,
        "updated_at": now,
    }
    results.append(res)
    _save("invocation_results.json", results)

    return {"invocation": inv, "result": res, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def run_bridge_test(aeHostId=None, applyTestEffects=None, templateName=None, settings=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Validate inputs (do not over-reject; accept any string id and resolve to an existing host or fall back)
    if aeHostId is not None and not isinstance(aeHostId, str):
        return _err("VALIDATION_ERROR", "aeHostId must be a string.", field="aeHostId")
    if applyTestEffects is not None and not isinstance(applyTestEffects, bool):
        return _err("VALIDATION_ERROR", "applyTestEffects must be a boolean.", field="applyTestEffects")

    allowed_templates = ["gaussian-blur", "directional-blur", "color-balance", "brightness-contrast", "curves", "glow", "drop-shadow", "cinematic-look", "text-pop"]
    if templateName is not None:
        if not isinstance(templateName, str):
            try:
                templateName = str(templateName)
            except Exception:
                return _err("VALIDATION_ERROR", "templateName must be a string.", field="templateName")
        if templateName not in allowed_templates:
            return _err("VALIDATION_ERROR", "templateName must be one of the allowed values.", field="templateName", allowed=allowed_templates)

    if settings is not None and not isinstance(settings, dict):
        return _err("VALIDATION_ERROR", "settings must be an object.", field="settings")

    clients = _load("mcp_clients.json")
    hosts = _load("ae_hosts.json")
    invocations = _load("tool_invocations.json")
    results = _load("invocation_results.json")

    if not isinstance(clients, list): clients = []
    if not isinstance(hosts, list): hosts = []
    if not isinstance(invocations, list): invocations = []
    if not isinstance(results, list): results = []

    # Ambient auth: choose active client with valid rate limit
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        rpm = c.get("rate_limit_rpm")
        if c.get("status") == "active" and isinstance(rpm, int) and 1 <= rpm <= 600:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "No active MCP client is authorized to call this tool.")

    # Choose AE host:
    # - If aeHostId is provided and matches an existing host, use it (even if offline; then fail with AE_HOST_UNAVAILABLE).
    # - If provided but doesn't match any host, fall back to any available host (online/degraded first), rather than NOT_FOUND.
    selected = None
    if isinstance(aeHostId, str) and aeHostId.strip():
        for h in hosts:
            if isinstance(h, dict) and h.get("id") == aeHostId:
                selected = h
                break
        if selected is None:
            # fall back: pick any host (prefer runnable)
            for h in hosts:
                if isinstance(h, dict) and h.get("status") in ("online", "degraded"):
                    selected = h
                    break
            if selected is None:
                selected = next((h for h in hosts if isinstance(h, dict) and h.get("id")), None)
    else:
        for h in hosts:
            if isinstance(h, dict) and h.get("status") in ("online", "degraded"):
                selected = h
                break
        if selected is None:
            selected = next((h for h in hosts if isinstance(h, dict) and h.get("id")), None)

    if selected is None:
        return _err("NOT_FOUND", "No AE host is configured.")

    ae_host_id = selected.get("id")

    # Rate limit (still record a failed invocation)
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    window_start = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("client_id") != client.get("id"):
            continue
        ca = _parse_dt(inv.get("created_at"))
        if ca and ca >= window_start:
            recent += 1

    inv_id = "aetool_" + uuid.uuid4().hex
    req_params = {}
    if aeHostId is not None: req_params["aeHostId"] = aeHostId
    if applyTestEffects is not None: req_params["applyTestEffects"] = applyTestEffects
    if templateName is not None: req_params["templateName"] = templateName
    if settings is not None: req_params["settings"] = settings

    if recent >= int(client.get("rate_limit_rpm")):
        inv_row = {
            "id": inv_id,
            "client_id": client.get("id"),
            "ae_host_id": ae_host_id,
            "tool_name": "run-bridge-test",
            "request_params": req_params,
            "status": "failed",
            "is_read_only": True,
            "started_at": None,
            "finished_at": now,
            "error_code": "RATE_LIMITED",
            "error_message": f"Client exceeded rate limit ({client.get('rate_limit_rpm')} rpm).",
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv_row)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", invocation=inv_row)

    # Host availability rule for AE-executing tools (run-bridge-test executes AE)
    if selected.get("status") not in ("online", "degraded"):
        inv_row = {
            "id": inv_id,
            "client_id": client.get("id"),
            "ae_host_id": ae_host_id,
            "tool_name": "run-bridge-test",
            "request_params": req_params,
            "status": "failed",
            "is_read_only": True,
            "started_at": None,
            "finished_at": now,
            "error_code": "AE_HOST_UNAVAILABLE",
            "error_message": f"AE host not ready (status={selected.get('status')}).",
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv_row)
        _save("tool_invocations.json", invocations)
        return {"invocation": inv_row, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

    # Succeed and store a result (bridge_test_report)
    inv_row = {
        "id": inv_id,
        "client_id": client.get("id"),
        "ae_host_id": ae_host_id,
        "tool_name": "run-bridge-test",
        "request_params": req_params,
        "status": "succeeded",
        "is_read_only": True,
        "started_at": now,
        "finished_at": now,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    invocations.append(inv_row)

    # maintain last-result pointer
    for r in results:
        if isinstance(r, dict) and r.get("client_id") == client.get("id") and r.get("ae_host_id") == ae_host_id and r.get("is_last_for_client") is True:
            r["is_last_for_client"] = False
            r["updated_at"] = now

    payload = {
        "aeHostId": ae_host_id,
        "hostStatus": selected.get("status"),
        "bridgeTransport": selected.get("bridge_transport"),
        "applyTestEffects": bool(applyTestEffects) if isinstance(applyTestEffects, bool) else False,
        "templateName": templateName,
        "settings": settings if isinstance(settings, dict) else {},
        "checks": {
            "ping": "ok",
            "extendscript": "ok",
        },
    }

    res_row = {
        "id": "aeres_" + uuid.uuid4().hex,
        "invocation_id": inv_id,
        "client_id": client.get("id"),
        "ae_host_id": ae_host_id,
        "result_kind": "bridge_test_report",
        "payload": payload,
        "is_last_for_client": True,
        "created_at": now,
        "updated_at": now,
    }
    results.append(res_row)

    # Update host last_seen_at as an observable dynamic
    if isinstance(selected, dict):
        selected["last_seen_at"] = now
        selected["updated_at"] = now
        _save("ae_hosts.json", hosts)

    _save("tool_invocations.json", invocations)
    _save("invocation_results.json", results)

    return {
        "invocation": inv_row,
        "result": res_row,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def list_tool_invocations(clientId=None, aeHostId=None, toolName=None, status=None, isReadOnly=None, createdAfter=None, createdBefore=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64

