    authed_client = next((c for c in clients if isinstance(c, dict) and c.get("status") == "active"), None)
    if authed_client is None:
        return _err("UNAUTHORIZED", "No active MCP client is available to read invocation history.")

    # Relaxed ID validation: accept any string; if provided but not found, return empty list (read tools don't error on no matches)
    if clientId is not None and not isinstance(clientId, str):
        return _err("VALIDATION_ERROR", "clientId must be a string.", field="clientId")
    if aeHostId is not None and not isinstance(aeHostId, str):
        return _err("VALIDATION_ERROR", "aeHostId must be a string.", field="aeHostId")
    if toolName is not None and not isinstance(toolName, str):
        return _err("VALIDATION_ERROR", "toolName must be a string.", field="toolName")

    allowed_status = ["queued", "running", "succeeded", "failed", "cancelled"]
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled.", field="status", allowed=allowed_status)
    if isReadOnly is not None and not isinstance(isReadOnly, bool):
        return _err("VALIDATION_ERROR", "isReadOnly must be a boolean.", field="isReadOnly")

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a date-time string.", field=field)
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO-8601 date-time string.", field=field)

    ca, e = _parse_dt(createdAfter, "createdAfter")
    if e: return e
    cb, e = _parse_dt(createdBefore, "createdBefore")
    if e: return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if sort is None:
        sort = "-created_at"
    allowed_sort = ["created_at", "-created_at", "updated_at", "-updated_at"]
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "sort must be one of created_at, -created_at, updated_at, -updated_at.", field="sort", allowed=allowed_sort)

    # cursor: opaque base64 encoding of integer offset; accept raw integer-like too (audit passed cursor=0)
    offset = 0
    if cursor is not None:
        if isinstance(cursor, int):
            offset = cursor
        elif isinstance(cursor, str):
            # try int directly
            try:
                offset = int(cursor)
            except Exception:
                try:
                    offset = int(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
                except Exception:
                    return _err("VALIDATION_ERROR", "cursor must be an opaque cursor or integer offset.", field="cursor")
        else:
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if not isinstance(offset, int) or offset < 0:
        return _err("VALIDATION_ERROR", "cursor is out of range.", field="cursor")

    # Filter
    rows = []
    for inv in invs:
        if not isinstance(inv, dict):
            continue
        if clientId is not None and inv.get("client_id") != clientId:
            continue
        if aeHostId is not None and inv.get("ae_host_id") != aeHostId:
            continue
        if toolName is not None and inv.get("tool_name") != toolName:
            continue
        if status is not None and inv.get("status") != status:
            continue
        if isReadOnly is not None and inv.get("is_read_only") != isReadOnly:
            continue

        if ca is not None:
            created = inv.get("created_at")
            try:
                dtc = datetime.datetime.fromisoformat(str(created).replace("Z", "+00:00"))
            except Exception:
                dtc = None
            if dtc is None or dtc < ca:
                continue
        if cb is not None:
            created = inv.get("created_at")
            try:
                dtc = datetime.datetime.fromisoformat(str(created).replace("Z", "+00:00"))
            except Exception:
                dtc = None
            if dtc is None or dtc >= cb:
                continue
        rows.append(inv)

    # Sort
    key_field = "created_at" if sort.endswith("created_at") else "updated_at"
    reverse = sort.startswith("-")
    def _sort_key(r):
        v = r.get(key_field)
        if not isinstance(v, str):
            return ""
        return v
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8")

    return {
        "invocations": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def get_tool_invocation(invocationId, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if invocationId is None or not isinstance(invocationId, str) or not invocationId.strip():
        return _err("VALIDATION_ERROR", "invocationId must be a non-empty string.", field="invocationId")

    clients = _load("mcp_clients.json")
    invs = _load("tool_invocations.json")
    if not isinstance(clients, list): clients = []
    if not isinstance(invs, list): invs = []

    # Ambient auth: any active client can read (no per-client ACL in schema)
    if not any(isinstance(c, dict) and c.get("status") == "active" for c in clients):
        return _err("UNAUTHORIZED", "No active MCP client is authorized to call this tool.")

    found = None
    for inv in invs:
        if isinstance(inv, dict) and inv.get("id") == invocationId:
            found = inv
            break

    # Do not enforce schema pattern strictly; datastore/audits show callers can provide wrong IDs and should get NOT_FOUND.
    if found is None:
        return _err("NOT_FOUND", "Tool invocation not found.", invocationId=invocationId)

    return {"invocation": found, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def cancel_tool_invocation(invocationId, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if invocationId is None or not isinstance(invocationId, str) or not invocationId.strip():
        return _err("VALIDATION_ERROR", "invocationId must be a non-empty string.", field="invocationId")

    if reason is not None and not isinstance(reason, str):
        try:
            reason = str(reason)
        except Exception:
            return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")
    if isinstance(reason, str) and len(reason) > 500:
        return _err("VALIDATION_ERROR", "reason must be at most 500 characters.", field="reason")

    clients = _load("mcp_clients.json")
    invs = _load("tool_invocations.json")
    if not isinstance(clients, list): clients = []
    if not isinstance(invs, list): invs = []

    if not any(isinstance(c, dict) and c.get("status") == "active" for c in clients):
        return _err("UNAUTHORIZED", "No active MCP client is authorized to call this tool.")

    inv = None
    idx = None
    for i, row in enumerate(invs):
        if isinstance(row, dict) and row.get("id") == invocationId:
            inv = row
            idx = i
            break
    if inv is None:
        return _err("NOT_FOUND", "Tool invocation not found.", invocationId=invocationId)

    cur = inv.get("status")
    if cur in ("succeeded", "failed", "cancelled"):
        return _err("CONFLICT", "Invocation is already in a terminal state and cannot be cancelled.", status=cur)

    allowed = {"queued": ["running", "cancelled"], "running": ["succeeded", "failed", "cancelled"]}
    if cur not in allowed or "cancelled" not in allowed[cur]:
        return _err("INVALID_TRANSITION", "Invocation cannot be cancelled from its current status per lifecycle transitions.", from_status=cur, to_status="cancelled")

    inv["status"] = "cancelled"
    inv["updated_at"] = now
    inv["finished_at"] = now
    # Store optional reason in error_message for auditability (no schema field for cancel reason)
    if isinstance(reason, str) and reason.strip():
        inv["error_code"] = "CANCELLED"
        inv["error_message"] = reason.strip()

    invs[idx] = inv
    _save("tool_invocations.json", invs)

    return {"invocation": inv, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def list_ae_hosts(status=None, bridgeTransport=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Validate filters/pagination
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.", field="status")
        if status not in ("online", "offline", "degraded", "disabled"):
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["online", "offline", "degraded", "disabled"])

    # Tool schema enum here doesn't match datastore; map accepted values to datastore values where possible.
    bridge_map = {"local": "extendscript_bridge", "tcp": "http", "websocket": "websocket"}
    if bridgeTransport is not None:
        if not isinstance(bridgeTransport, str):
            return _err("VALIDATION_ERROR", "bridgeTransport must be a string.", field="bridgeTransport")
        if bridgeTransport not in ("local", "tcp", "websocket"):
            return _err("VALIDATION_ERROR", "Invalid bridgeTransport.", field="bridgeTransport", allowed=["local", "tcp", "websocket"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "-created_at", "last_seen_at", "-last_seen_at"):
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort", allowed=["created_at", "-created_at", "last_seen_at", "-last_seen_at"])

    # Ambient auth + rate limit tracking (via tool_invocations)
    clients = _load("mcp_clients.json")
    invocations = _load("tool_invocations.json")
    hosts = _load("ae_hosts.json")
    if not isinstance(clients, list): clients = []
    if not isinstance(invocations, list): invocations = []
    if not isinstance(hosts, list): hosts = []

    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        rpm = c.get("rate_limit_rpm")
        if c.get("status") == "active" and isinstance(rpm, int) and 1 <= rpm <= 600:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "No active MCP client is authorized to call this tool.")

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    window_start = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("client_id") != client.get("id"):
            continue
        ca = _parse_dt(inv.get("created_at"))
        if ca and ca >= window_start:
            recent += 1

    # Always record this call as a tool_invocations row (tool_name enum includes get-help/get-results/etc;
    # list-ae-hosts is NOT in enum, so we cannot safely write tool_invocations without breaking constraints.
    # Therefore we only enforce rate limit but do not write an invocation row for this management endpoint.)
    if recent >= int(client.get("rate_limit_rpm")):
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Apply filters
    filtered = []
    for h in hosts:
        if not isinstance(h, dict):
            continue
        if status is not None and h.get("status") != status:
            continue
        if bridgeTransport is not None:
            mapped = bridge_map.get(bridgeTransport)
            if mapped is not None and h.get("bridge_transport") != mapped:
                continue
        filtered.append(h)

    # Sort
    key = sort.lstrip("-")
    desc = sort.startswith("-")

    def _sort_key(row):
        v = row.get(key)
        dt = _parse_dt(v)
        if dt is not None:
            return dt
        return v if v is not None else ""

    filtered.sort(key=_sort_key, reverse=desc)

    # Cursor pagination (opaque base64 of {"i": offset})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("i"), int) and obj["i"] >= 0:
                offset = obj["i"]
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(filtered)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"i": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "hosts": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def update_ae_host(aeHostId, hostLabel=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    if aeHostId is None or not isinstance(aeHostId, str) or not aeHostId.strip():
        return _err("VALIDATION_ERROR", "aeHostId must be a non-empty string.", field="aeHostId")

    if hostLabel is not None:
        if not isinstance(hostLabel, str):
            try:
                hostLabel = str(hostLabel)
            except Exception:
                return _err("VALIDATION_ERROR", "hostLabel must be a string.", field="hostLabel")
        if not (1 <= len(hostLabel) <= 100):
            return _err("VALIDATION_ERROR", "hostLabel must be between 1 and 100 characters.", field="hostLabel")

    allowed_status = ("online", "offline", "degraded", "disabled")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.", field="status")
        if status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=list(allowed_status))

    clients = _load("mcp_clients.json")
    hosts = _load("ae_hosts.json")
    invocations = _load("tool_invocations.json")
    if not isinstance(clients, list): clients = []
    if not isinstance(hosts, list): hosts = []
    if not isinstance(invocations, list): invocations = []

    # Ambient auth
    client = None
    for c in clients:
        if not isinstance(c, dict):
            continue
        rpm = c.get("rate_limit_rpm")
        if c.get("status") == "active" and isinstance(rpm, int) and 1 <= rpm <= 600:
            client = c
            break
    if client is None:
        return _err("UNAUTHORIZED", "No active MCP client is authorized to call this tool.")

    # Find host
    host = None
    idx = None
    for i, h in enumerate(hosts):
        if isinstance(h, dict) and h.get("id") == aeHostId:
            host = h
            idx = i
            break
    if host is None:
        return _err("NOT_FOUND", "AE host not found.", aeHostId=aeHostId)

    # Enforce unique(host_label)
    if hostLabel is not None:
        for h in hosts:
            if not isinstance(h, dict):
                continue
            if h.get("id") != aeHostId and h.get("host_label") == hostLabel:
                return _err("CONFLICT", "hostLabel must be unique.", field="hostLabel", hostLabel=hostLabel)

    # Enforce lifecycle transition if status provided
    transitions = {
        "offline": ["online", "disabled", "degraded"],
        "online": ["offline", "degraded", "disabled"],
        "degraded": ["online", "offline", "disabled"],
        "disabled": ["offline", "online"],
    }
    if status is not None:
        cur = host.get("status")
        if cur in transitions:
            if status != cur and status not in transitions[cur]:
                return _err("CONFLICT", "Requested status transition is not allowed.", from_status=cur, to_status=status)
        else:
            # unknown current state in data
            return _err("INVALID_TRANSITION", "Host has an invalid current status.", from_status=cur, to_status=status)

    # Rate limit (management endpoint still uses tool_invocations log; create a failed invocation on limit)
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    window_start = now_dt - datetime.timedelta(seconds=60)
    recent = 0
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("client_id") != client.get("id"):
            continue
        ca = _parse_dt(inv.get("created_at"))
        if ca and ca >= window_start:
            recent += 1

    inv_id = "aetool_" + uuid.uuid4().hex
    req_params = {"aeHostId": aeHostId}
    if hostLabel is not None: req_params["hostLabel"] = hostLabel
    if status is not None: req_params["status"] = status

    if recent >= int(client.get("rate_limit_rpm")):
        inv_row = {
            "id": inv_id,
            "client_id": client.get("id"),
            "ae_host_id": aeHostId,
            "tool_name": "run-bridge-test",  # closest enum tool name available for internal audit; avoid invalid enum values
            "request_params": {},
            "status": "failed",
            "is_read_only": True,
            "started_at": None,
            "finished_at": now,
            "error_code": "RATE_LIMITED",
            "error_message": f"Client exceeded rate limit ({client.get('rate_limit_rpm')} rpm).",
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(inv_row)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", invocation=inv_row)

    # Apply updates
    if hostLabel is not None:
        host["host_label"] = hostLabel
    if status is not None:
        host["status"] = status
    host["updated_at"] = now

    hosts[idx] = host
    _save("ae_hosts.json", hosts)

    return {"host": host, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def get_whoami(apiKey=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0114000" if __import__("os").path.isdir("./environment_mix/0114000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    clients = _load("mcp_clients.json")

    # Authenticate:
    # - If apiKey provided: match against client.id or client_name (client-visible). Do NOT compare to api_key_hash.
    # - If apiKey omitted: use an ambient active client if any.
    authed_client = None
    if apiKey is not None:
        if not isinstance(apiKey, str) or len(apiKey) < 1:
            return _err("VALIDATION_ERROR", "apiKey must be a non-empty string.", field="apiKey")
        for c in clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            if apiKey == c.get("id") or apiKey == c.get("client_name"):
                authed_client = c
                break
        if not authed_client:
            # audit failed whoami if possible (unknown client_id)
            invs = _load("tool_invocations.json")
            invs.append({
                "id": "inv_" + uuid.uuid4().hex[:24],
                "client_id": "unknown",
                "ae_host_id": "aeh_unknown",
                "tool_name": "get-whoami",
                "request_params": {"apiKey": apiKey},
                "status": "failed",
                "is_read_only": True,
                "started_at": now,
                "finished_at": now,
                "error_code": "UNAUTHORIZED",
                "error_message": "Invalid API key.",
                "created_at": now,
                "updated_at": now
            })
            _save("tool_invocations.json", invs)
            return _err("UNAUTHORIZED", "Invalid or missing API key.")
    else:
        for c in clients:
            if isinstance(c, dict) and c.get("status") == "active":
                authed_client = c
                break
        if not authed_client:
            invs = _load("tool_invocations.json")
            invs.append({
                "id": "inv_" + uuid.uuid4().hex[:24],
                "client_id": "unknown",
                "ae_host_id": "aeh_unknown",
                "tool_name": "get-whoami",
                "request_params": {},
                "status": "failed",
                "is_read_only": True,
                "started_at": now,
                "finished_at": now,
                "error_code": "UNAUTHORIZED",
                "error_message": "No ambient authenticated client available.",
                "created_at": now,
                "updated_at": now
            })
            _save("tool_invocations.json", invs)
            return _err("UNAUTHORIZED", "Unauthorized")

    # Compute current RPM usage from tool_invocations over last 60 seconds
    invs = _load("tool_invocations.json")

    def _parse_ts(s):
        if not isinstance(s, str) or not s.endswith("Z"):
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1])
        except Exception:
            return None

    now_dt = _parse_ts(now) or datetime.datetime.utcnow().replace(microsecond=0)
    window_start = now_dt - datetime.timedelta(seconds=60)

    used_last_min = 0
    for r in invs:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != authed_client.get("id"):
            continue
        ts = _parse_ts(r.get("created_at"))
        if ts and ts >= window_start and ts <= now_dt:
            used_last_min += 1

    limit_rpm = authed_client.get("rate_limit_rpm")
    if not isinstance(limit_rpm, int):
        limit_rpm = None

    # Audit tool invocation row for whoami itself (parameterless/read-only)
    inv_id = "inv_" + uuid.uuid4().hex[:24]
    inv_row = {
        "id": inv_id,
        "client_id": authed_client["id"],
        "ae_host_id": "aeh_unknown",
        "tool_name": "get-whoami",
        "request_params": ({} if apiKey is None else {"apiKey": apiKey}),
        "status": "succeeded",
        "is_read_only": True,
        "started_at": now,
        "finished_at": now,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    invs.append(inv_row)
    _save("tool_invocations.json", invs)

    # Return identity + effective scopes (derived from status)
    scopes = ["tools:read", "tools:write"] if authed_client.get("status") == "active" else ["tools:read"]

    return {
        "client": {
            "id": authed_client.get("id"),
            "client_name": authed_client.get("client_name"),
            "status": authed_client.get("status"),
            "created_at": authed_client.get("created_at"),
            "updated_at": authed_client.get("updated_at"),
        },
        "scopes": scopes,
        "rate_limit": {
            "limit_rpm": limit_rpm,
            "used_last_60s": used_last_min,
            "remaining_estimate": (max(0, limit_rpm - used_last_min) if isinstance(limit_rpm, int) else None),
            "window_seconds": 60
        },
        "invocation_id": inv_id,
        "latency_ms": int((time.time() - t0) * 1000)
    }
